Given the root of a Binary Tree with unique values and two node values n1 and n2, find the Lowest Common Ancestor (LCA). LCA is the deepest node that has both n1 and n2 as descendants.Note: Both node values are always present in the Binary Tree.Examples:Input: n1 .data= 4, n2.data = 5 Output: 2Explanation: As shown below, LCA of 4 and 5 is 2. Input: n1.data = 7, n2.data = 8 Output: 3Explanation: As shown below, LCA of 7 and 8 is 3. Try It YourselfTable of Content[Naive Approach] Checking if each node is LCA - O(N2) Time and O(h) space[Better Approach] Storing Paths of Nodes from Root - O(n) Time and O(n) Space[Expected Approach] Using Single Traversal[Naive Approach] Checking if each node is LCA - O(N^2) Time and O(h) spaceThe idea is to traverse the tree from root node, and for every node check if it is the LCA.A node is the LCA if its left subtree has one target node and right subtree has the other target node.
            C++

    #include <iostream>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int value) {
        data = value;
        left = right = nullptr;
    }
};

// returns true if val is present 
// in the subtree of root
bool hasNode(Node* root, Node* node) {
    if (root == nullptr) return false;
    return (root == node) || 
            hasNode(root->left, node) || 
            hasNode(root->right, node);
}

Node* lca(Node* root, Node* n1, Node* n2) {
    if (root == nullptr) return nullptr;

    if (hasNode(root->left, n1) && hasNode(root->right, n2))
        return root;

    if (hasNode(root->left, n2) && hasNode(root->right, n1))
        return root;

    Node* lcaLeft = lca(root->left, n1, n2);
    Node* lcaRight = lca(root->right, n1, n2);

    return lcaLeft != nullptr ? lcaLeft : lcaRight;
}

int main() {
    // Create binary tree:
    //			   1
    //           /   \
    //          2     3
    //               / \
    //              6   7 
    //             /
    //            8

    Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->right->left = new Node(6);
    root->right->right = new Node(7);
    root->right->left->left = new Node(8);

    // Node 7
    Node* n1 = root->right->right;

    // Node 8
    Node* n2 = root->right->left->left;

    Node* ans = lca(root, n1, n2);
    cout << ans->data << endl;
}


